import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        int rows = next(in), cols = next(in);
        boolean[] wall = new boolean[rows * cols];
        int[] gem = new int[rows * cols];
        for (int k = next(in); k > 0; k--) { int r = next(in), c = next(in); wall[r * cols + c] = true; }
        for (int k = next(in); k > 0; k--) { int r = next(in), c = next(in); gem[r * cols + c] = 1; }
        int s = next(in) * cols; s += next(in);
        int e = next(in) * cols; e += next(in);
        if (wall[s] || wall[e]) { System.out.println("-1 0"); return; }
        int[] dist = new int[rows * cols], best = new int[rows * cols];
        Arrays.fill(dist, -1);
        int[] q = new int[rows * cols];
        int head = 0, tail = 0;
        q[tail++] = s; dist[s] = 0; best[s] = gem[s];
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        while (head < tail) {
            int cur = q[head++], x = cur / cols, y = cur % cols;
            for (int d = 0; d < 4; d++) {
                int nx = x + dr[d], ny = y + dc[d];
                if (nx < 0 || nx >= rows || ny < 0 || ny >= cols) continue;
                int z = nx * cols + ny;
                if (wall[z]) continue;
                if (dist[z] < 0) { dist[z] = dist[cur] + 1; best[z] = best[cur] + gem[z]; q[tail++] = z; }
                else if (dist[z] == dist[cur] + 1) best[z] = Math.max(best[z], best[cur] + gem[z]);
            }
        }
        System.out.println(dist[e] < 0 ? "-1 0" : dist[e] + " " + best[e]);
    }

    static int next(StreamTokenizer in) throws IOException {
        in.nextToken();
        return (int) in.nval;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	rows, cols := next(), next()
	wall := make([]bool, rows*cols)
	gem := make([]int, rows*cols)
	for k := next(); k > 0; k-- {
		r, c := next(), next()
		wall[r*cols+c] = true
	}
	for k := next(); k > 0; k-- {
		r, c := next(), next()
		gem[r*cols+c] = 1
	}
	sr, scol := next(), next()
	er, ec := next(), next()
	s, e := sr*cols+scol, er*cols+ec
	if wall[s] || wall[e] {
		fmt.Println("-1 0")
		return
	}
	dist := make([]int, rows*cols)
	best := make([]int, rows*cols)
	for i := range dist {
		dist[i] = -1
	}
	dist[s], best[s] = 0, gem[s]
	q := []int{s}
	dr, dc := []int{1, -1, 0, 0}, []int{0, 0, 1, -1}
	for head := 0; head < len(q); head++ {
		cur := q[head]
		x, y := cur/cols, cur%cols
		for d := 0; d < 4; d++ {
			nx, ny := x+dr[d], y+dc[d]
			if nx < 0 || nx >= rows || ny < 0 || ny >= cols {
				continue
			}
			z := nx*cols + ny
			if wall[z] {
				continue
			}
			if dist[z] < 0 {
				dist[z], best[z] = dist[cur]+1, best[cur]+gem[z]
				q = append(q, z)
			} else if dist[z] == dist[cur]+1 {
				best[z] = max(best[z], best[cur]+gem[z])
			}
		}
	}
	if dist[e] < 0 {
		fmt.Println("-1 0")
	} else {
		fmt.Println(dist[e], best[e])
	}
}
